//! GSS -> checked DIMACS -> bounded reference model count.
//!
//! The fixture is generated by `tools/gss_to_dimacs.py` from a native GSS
//! file. This checks ingestion, not execution of the unfinished ETH counter.
use lean_eth_reference::{EnumeratingLeaf, Limits, count_cnf, parse_dimacs};

const LATIN_2X2: &str = include_str!("../fixtures/gss/latin_2x2.cnf");

fn independent_legal_grids() -> usize {
    let mut total = 0;
    for a in 1..=2 {
        for b in 1..=2 {
            for c in 1..=2 {
                for d in 1..=2 {
                    if a != b && c != d && a != c && b != d {
                        total += 1;
                    }
                }
            }
        }
    }
    total
}

#[test]
fn native_gss_fixture_enters_dimacs_parser_without_loss_of_models() {
    let formula = parse_dimacs(LATIN_2X2).expect("generated 2x2 GSS DIMACS");
    assert_eq!(formula.variables(), 8);
    assert_eq!(formula.clauses().len(), 24);
    assert!(formula.clauses().iter().all(|c| c.literals().len() <= 3));

    let expected = independent_legal_grids();
    assert_eq!(expected, 2);

    // This is the repository's deliberately exponential reference leaf,
    // not the unported source-defined QueryStream/DFS counter.
    let (count, _) = count_cnf(
        formula.normalize(),
        2,
        &mut EnumeratingLeaf { max_variables: 8 },
        Limits::default(),
    )
    .expect("bounded independent sanity check");
    assert_eq!(count, expected as u128);
}
